module tb;
bit clk=0; always #5 clk=~clk;
logic [31:0] instr; logic instr_new; logic [2:0] illegal,expected; integer sample_id=-1,txn_id=-1,phase=-1;
ibex_decoder #(.RV32E(0),.RV32M(1)) dut_0(.instr_new_i(instr_new),.instr_rdata_i(instr),.illegal_c_insn_i(1'b0),.illegal_insn_o(illegal[0]));
assert property (@(posedge clk) (sample_id>=0) |-> (illegal[0]==expected[0])) else $display("ASSERT_FAIL isa_0 sample=%0d txn=%0d phase=%0d",sample_id,txn_id,phase);
ibex_decoder #(.RV32E(0),.RV32M(0)) dut_1(.instr_new_i(instr_new),.instr_rdata_i(instr),.illegal_c_insn_i(1'b0),.illegal_insn_o(illegal[1]));
assert property (@(posedge clk) (sample_id>=0) |-> (illegal[1]==expected[1])) else $display("ASSERT_FAIL isa_1 sample=%0d txn=%0d phase=%0d",sample_id,txn_id,phase);
ibex_decoder #(.RV32E(1),.RV32M(1)) dut_2(.instr_new_i(instr_new),.instr_rdata_i(instr),.illegal_c_insn_i(1'b0),.illegal_insn_o(illegal[2]));
assert property (@(posedge clk) (sample_id>=0) |-> (illegal[2]==expected[2])) else $display("ASSERT_FAIL isa_2 sample=%0d txn=%0d phase=%0d",sample_id,txn_id,phase);
always @(posedge clk) if(sample_id>=0) begin
$display("TRIGGER isa sample=%0d",sample_id);
$display("TRACE sample=%0d txn=%0d phase=%0d instr=%h new=%b expected=%b observed=%b",sample_id,txn_id,phase,instr,instr_new,expected,illegal);
end
